import {getAction} from '@madou/catalog';
import {createGame,gameStats,transition,allCardInstanceIds,type GameCommand} from '@madou/engine';
import {assignCharacter,entropy,takeCard,trimHand} from './scenario-tools.js';
export const blackDragonCard='a2-p09-r1c3';
export const blackDragonScenarios=['black-dragon-ordinary', 'black-dragon-guard', 'black-dragon-owner-ordinary', 'black-dragon-low', 'black-dragon-dedicated', 'black-dragon-far', 'black-dragon-same-faction', 'black-dragon-nonwhite', 'black-dragon-lower', 'black-dragon-maai', 'black-dragon-evade', 'black-dragon-fate', 'black-dragon-suppressed', 'black-dragon-silenced', 'black-dragon-stopped', 'black-dragon-wrong-owner', 'black-dragon-decline', 'black-dragon-noncounter', 'black-dragon-double', 'black-dragon-double-fail', 'black-dragon-double-decline', 'black-dragon-double-lowspirit', 'black-dragon-double-lower', 'black-dragon-double-maai', 'black-dragon-double-evade', 'black-dragon-double-force-fail', 'black-dragon-double-reroll', 'black-dragon-double-force-reroll'] as const;
export type BlackDragonScenario=typeof blackDragonScenarios[number];
export function isBlackDragonScenario(name:string):name is BlackDragonScenario{return (blackDragonScenarios as readonly string[]).includes(name);}
export function blackDragonMode(name:BlackDragonScenario){const suffix=name.replace('black-dragon-',''),dedicated=!['ordinary','guard','owner-ordinary','low','decline'].includes(suffix),owner=dedicated&&suffix!=='wrong-owner'||suffix==='owner-ordinary',followers=['ordinary','low','decline'].includes(suffix)?[]:suffix==='nonwhite'?['a2-p22-r1c1']:['lower','double-lower'].includes(suffix)?['a2-p19-r1c3']:['a2-p22-r3c3'],attempt=suffix.startsWith('double')&&suffix!=='double-decline'||['suppressed','silenced'].includes(suffix);return {suffix,dedicated,owner,followers,attempt};}
export function makeBlackDragonPhysical(name:BlackDragonScenario,players:{id:string;name:string}[],options:{beforeStart?:boolean;warrior?:number;spirit?:number}={}){
 const m=blackDragonMode(name),prior=['suppressed','stopped','silenced'].includes(m.suffix),incoming=m.suffix==='noncounter';let s=createGame(players,entropy(),{startingSeat:prior?3:incoming?1:0});const [a,b,c,d]=players.map(p=>p.id) as [string,string,string,string];
 for(const [i,p] of players.entries())assignCharacter(s,p.id,[m.owner?'黒騎士ガーウィン':'侍大将のシン',m.owner?'侍大将のシン':'獣使いのウパニシャット','黒妖精のアーネス','聖騎士ランスロット'][i]!);
 for(const p of Object.values(s.players)){p.permanent={endurance:100,warrior_level:20,magic_level:20,spirit:20};p.permanent.spirit!+=(p.id===a?options.spirit??(m.suffix==='double-lowspirit'?0:6):6)-gameStats(s,p.id).spirit;}
 s.players[a]!.permanent!.warrior_level!+=(options.warrior??(m.suffix==='low'?4:m.dedicated?0:5))-gameStats(s,a).warrior_level;
 const keep=[takeCard(s,a,blackDragonCard),takeCard(s,a,'a2-p24-r1c3'),takeCard(s,d,'a2-p02-r2c3')];for(const id of m.followers)keep.push(takeCard(s,b,id));if(m.followers.length)keep.push(takeCard(s,c,'a2-p18-r3c3'));
 if(m.suffix==='same-faction')keep.push(takeCard(s,a,'a2-p24-r2c1'));if(m.suffix==='maai'||m.suffix==='double-maai')keep.push(takeCard(s,b,'a2-p06-r1c3'));if(m.suffix==='evade'||m.suffix==='double-evade')keep.push(takeCard(s,b,'a2-p05-r3c1'));if(m.suffix.includes('reroll'))keep.push(takeCard(s,c,'a2-p02-r1c3'));if(incoming)keep.push(takeCard(s,b,'a2-p24-r1c2'));if(prior)keep.push(takeCard(s,d,m.suffix==='suppressed'?'a2-p13-r1c2':m.suffix==='stopped'?'a2-p13-r2c1':'a2-p18-r1c1'));
 for(const p of players)trimHand(s,p.id,...keep);s.deck=[...s.deck.filter(id=>getAction(id)!.category!=='open'),...s.deck.filter(id=>getAction(id)!.category==='open')];s.events=[];
 function act(actorId:string,command:GameCommand,face=1){const input={actorId,command},e={...entropy(),dice:Array(100).fill(face)},r=transition(s,input,e);if(!r.ok)throw Error(`BLACK_DRAGON_FIXTURE_${command.type}_${r.code}`);if(JSON.stringify(r)!==JSON.stringify(transition(JSON.parse(JSON.stringify(s)),input,e)))throw Error('BLACK_DRAGON_FIXTURE_REPLAY');s=r.state;const ids=allCardInstanceIds(s);if(ids.length!==220||new Set(ids).size!==220)throw Error('BLACK_DRAGON_FIXTURE_CARDS');}
 function settle(face=1){for(let n=0;n<600;n++){const w=s.windows?.at(-1);if(!w)return;act(w.participants[w.cursor]!,{type:'PASS'},face);}throw Error('BLACK_DRAGON_FIXTURE_LIMIT');}
 for(const id of [a,b,c,d]){if(id===b)for(const cardInstanceId of m.followers)act(b,{type:'PLACE_INITIAL_FOLLOWER',cardInstanceId});if(id===c&&m.followers.length)act(c,{type:'PLACE_INITIAL_FOLLOWER',cardInstanceId:'a2-p18-r3c3'});act(id,{type:'PASS_SETUP'});}if(options.beforeStart)return s;
 if(prior){act(d,{type:'START_TURN'});settle();act(d,{type:'CHOOSE_DRAW',draw:false});act(d,{type:'ATTACK',cardInstanceId:m.suffix==='suppressed'?'a2-p13-r1c2':m.suffix==='stopped'?'a2-p13-r2c1':'a2-p18-r1c1',targetIds:[a],dedicated:false});settle(6);if(s.phase==='withdrawal')act(d,{type:'PASS_WITHDRAWAL'});act(d,{type:'END_TURN',discardIds:[]});settle();}
 const starter=incoming?b:a;act(starter,{type:'START_TURN'});settle(prior?6:1);if(s.phase==='draw')act(starter,{type:'CHOOSE_DRAW',draw:false});if(incoming){act(b,{type:'ATTACK',cardInstanceId:'a2-p24-r1c2',targetIds:[a],dedicated:false});for(let n=0;n<400;n++){const w=s.windows!.at(-1)!;if(w.kind==='normal-defense')return s;act(w.participants[w.cursor]!,{type:'PASS'});}throw Error('BLACK_DRAGON_FIXTURE_COUNTER_LIMIT');}
 if(!['far','stopped'].includes(m.suffix)){act(a,{type:'APPROACH',cardInstanceId:'a2-p24-r1c3',targetId:b});settle();}if(m.suffix==='same-faction'){act(a,{type:'APPROACH',cardInstanceId:'a2-p24-r2c1',targetId:c});settle();act(c,{type:'REVEAL_CHARACTER'});settle();}return s;
}
